  webhook: 'bg-orange-500/20 text-orange-400',
  sdk: 'bg-gray-500/20 text-gray-400',
  'project-chat': 'bg-cyan-500/20 text-cyan-400',
}

function healthColor(rate: number): string {
  if (rate >= 90) return 'text-green-400'
  if (rate >= 70) return 'text-yellow-400'
  return 'text-red-400'
}

// Groups runs by day offset (0=today, 1=yesterday, ...) for 7 days
function buildTrend(runs: AgentRunEntry[]): { label: string; success: number; error: number; total: number }[] {
  const days: { label: string; success: number; error: number; total: number }[] = []
  const now = Date.now()
  for (let i = 6; i >= 0; i--) {
    const dayStart = now - i * 86400000
    const dayEnd = dayStart + 86400000
    const dayRuns = runs.filter(r => {
      const t = new Date(r.timestamp).getTime()
      return t >= dayStart && t < dayEnd
    })
    const d = new Date(dayStart)
    days.push({
      label: d.toLocaleDateString('en-US', { weekday: 'short' }),
      success: dayRuns.filter(r => r.status === 'success').length,
      error: dayRuns.filter(r => r.status === 'error').length,
      total: dayRuns.length,
    })
  }
  return days
}

export default function Dashboard({ projects }: Props) {
  const navigate = useNavigate()
  const [runs, setRuns] = useState<AgentRunEntry[]>([])
  const [summary, setSummary] = useState<AgentAnalyticsSummary>({})
  const [schedules, setSchedules] = useState<Schedule[]>([])
  const [savings, setSavings] = useState<RoutingSavings | null>(null)
  const [loading, setLoading] = useState(true)

  useEffect(() => {
    Promise.all([
      getAnalyticsRuns({ limit: 200 }).catch(() => ({ runs: [], total: 0 })),
      getAnalyticsSummary().catch(() => ({})),
      getSchedules().catch(() => []),
      getRoutingSavings().catch(() => null),
    ]).then(([r, s, sc, sv]) => {
      setRuns(r.runs)
      setSummary(s)
      setSchedules(sc)
      setSavings(sv)
    }).finally(() => setLoading(false))
  }, [])

  const todayRuns = useMemo(() =>
    runs.filter(r => Date.now() - new Date(r.timestamp).getTime() < 86400000), [runs])

  const successRate = todayRuns.length > 0
    ? Math.round(todayRuns.filter(r => r.status === 'success').length / todayRuns.length * 100)
    : 100

  const activeSchedules = schedules.filter(s => s.enabled).length

  const topAgents = useMemo(() =>
    Object.entries(summary).sort(([, a], [, b]) => b.runCount - a.runCount).slice(0, 5),
    [summary])

  const trend = useMemo(() => buildTrend(runs), [runs])
  const maxTrend = Math.max(...trend.map(d => d.total), 1)

  if (loading) return (
    <div className="p-8 flex items-center justify-center h-64">
      <div className="w-6 h-6 border-2 border-accent border-t-transparent rounded-full animate-spin" />
    </div>
  )

  return (
    <div className="p-6 max-w-6xl">
      {/* Header */}
      <div className="mb-6">
        <h1 className="text-xl font-bold tracking-tight">Dashboard</h1>
        <p className="text-xs text-text-muted mt-0.5">Agent operations at a glance</p>
      </div>

      {/* Quick actions */}
      <div className="grid grid-cols-4 gap-3 mb-6">
        {[
          { label: 'Run Agent', icon: FlaskConical, path: '/playground', color: 'text-purple-400', bg: 'bg-purple-500/10' },
          { label: 'Orchestrate', icon: Sparkles, path: '/orchestration', color: 'text-blue-400', bg: 'bg-blue-500/10' },
          { label: 'Agents', icon: Bot, path: '/agents', color: 'text-accent', bg: 'bg-accent/10', sub: `${Object.keys(summary).length || 0} active` },
          { label: 'Projects', icon: FolderOpen, path: '/settings', color: 'text-amber-400', bg: 'bg-amber-500/10', sub: `${projects.length}` },
        ].map(q => (
          <button
            key={q.label}
            onClick={() => navigate(q.path)}
            className="bg-surface rounded-xl border border-border p-4 flex items-center gap-3 hover:border-accent/20 transition-all text-left group"
          >
            <div className={`p-2 rounded-lg ${q.bg} ${q.color}`}>
              <q.icon className="w-4 h-4" />
            </div>
            <div>
              <span className="text-sm font-semibold group-hover:text-accent-hover transition-colors">{q.label}</span>
              {q.sub && <p className="text-[10px] text-text-muted">{q.sub}</p>}
            </div>
          </button>
        ))}
      </div>

import { useState, useEffect } from 'react'
import { Settings, Trash2, Save, FolderOpen, Info, FolderSearch } from 'lucide-react'
import { getConfig, updateProjectDirs, getGlobalSettings, updateGlobalSettings } from '../lib/api'
import { useApi } from '../hooks/useApi'
import DirectoryPicker from '../components/DirectoryPicker'
import { toast } from '../components/Toast'

interface Props {
  onSave: () => void
}

export default function SettingsPage({ onSave }: Props) {
  const { data: config, loading } = useApi(getConfig)
  const [dirs, setDirs] = useState<string[]>([])
  const [saving, setSaving] = useState(false)
  const [dirty, setDirty] = useState(false)
  const [pickerOpen, setPickerOpen] = useState(false)

  const { data: settingsRaw, loading: settingsLoading } = useApi(getGlobalSettings)
  const [settingsData, setSettingsData] = useState<Record<string, unknown>>({})
  const [settingsPermissionsText, setSettingsPermissionsText] = useState('{}')
  const [settingsPermissionsError, setSettingsPermissionsError] = useState('')
  const [settingsDirty, setSettingsDirty] = useState(false)
  const [savingSettings, setSavingSettings] = useState(false)

  useEffect(() => {
    if (settingsRaw) {
      setSettingsData(settingsRaw)
      setSettingsPermissionsText(JSON.stringify((settingsRaw.permissions as object) || {}, null, 2))
      setSettingsDirty(false)
    }
  }, [settingsRaw])

  const handleSaveSettings = async () => {
    try {
      const parsed = JSON.parse(settingsPermissionsText)
      setSettingsPermissionsError('')
      setSavingSettings(true)
      const merged = { ...settingsData, permissions: parsed }
      await updateGlobalSettings(merged)
      setSettingsDirty(false)
      toast('success', 'Claude settings saved')
    } catch {
      setSettingsPermissionsError('Invalid JSON — fix before saving')
      return
    } finally {
      setSavingSettings(false)
    }
  }

  useEffect(() => {
    if (config) {
      setDirs(config.projectDirs || [])
      setDirty(false)
    }
  }, [config])

  const handleAddFromPicker = (dirPath: string) => {
    const display = dirPath.replace(/^\/Users\/[^/]+/, '~')
    if (!dirs.includes(dirPath) && !dirs.includes(display)) {
      setDirs([...dirs, display])
      setDirty(true)
    }
  }

  const handleRemove = (dir: string) => {
    setDirs(prev => prev.filter(d => d !== dir))
    setDirty(true)
  }

  const handleSave = async () => {
    setSaving(true)
    try {
      await updateProjectDirs(dirs)
      setDirty(false)
      onSave()
      toast('success', 'Settings saved')
    } catch (err) {
      toast('error', err instanceof Error ? err.message : 'Failed to save settings')
    } finally {
      setSaving(false)
    }
  }

  if (loading) {
    return (
      <div className="p-8 flex items-center justify-center h-64">
        <div className="w-6 h-6 border-2 border-accent border-t-transparent rounded-full animate-spin" />
      </div>
    )
  }

  return (
    <div className="p-8 max-w-3xl">
      <div className="flex items-center justify-between mb-6">
        <div>
          <h1 className="text-2xl font-semibold tracking-tight flex items-center gap-3">
            <Settings className="w-6 h-6 text-text-secondary" />
            Settings
          </h1>
          <p className="text-text-secondary text-sm mt-1">
            Configure Polyglot
          </p>
        </div>
        <button
          onClick={handleSave}
          disabled={!dirty || saving}
          className="flex items-center gap-2 px-4 py-2 text-sm font-medium bg-accent text-white rounded-lg hover:bg-accent-hover disabled:opacity-40 disabled:cursor-not-allowed transition-colors"
        >
          <Save className="w-4 h-4" />
          {saving ? 'Saving...' : 'Save'}
        </button>
      </div>

      {/* Info */}
      <div className="bg-accent-muted border border-accent/20 rounded-xl p-4 mb-6 flex items-start gap-3">
        <Info className="w-5 h-5 text-accent shrink-0 mt-0.5" />
        <div className="text-sm text-accent-hover">
          <p className="font-medium mb-1">How project discovery works</p>
          <p className="text-text-secondary">
            Add parent directories below. Polyglot scans each directory for subdirectories
            containing <code className="text-accent font-mono text-xs">.claude/</code>,{' '}
            <code className="text-accent font-mono text-xs">CLAUDE.md</code>, or{' '}
            <code className="text-accent font-mono text-xs">package.json</code>.
          </p>
        </div>
      </div>

      {/* Claude directory info */}
      <div className="bg-surface border border-border rounded-xl p-5 mb-6">
        <div className="flex items-center gap-3">
          <FolderOpen className="w-5 h-5 text-text-muted" />
          <div>
            <p className="text-sm font-medium">Claude Directory</p>
            <p className="text-xs text-text-muted font-mono">{config?.claudeDir}</p>
          </div>
          <span
            className={`ml-auto text-xs px-2 py-1 rounded-md ${
              config?.claudeDirExists
                ? 'bg-green-muted text-green'
                : 'bg-red-muted text-red'
            }`}
          >
            {config?.claudeDirExists ? 'Found' : 'Not found'}
          </span>
        </div>
      </div>

      {/* Project Directories */}
      <div className="bg-surface border border-border rounded-xl p-5">
        <div className="flex items-center justify-between mb-4">
          <h2 className="text-base font-semibold">Project Directories</h2>
          <button
            onClick={() => setPickerOpen(true)}
            className="flex items-center gap-2 px-4 py-2 text-sm font-medium bg-accent text-white rounded-lg hover:bg-accent-hover transition-colors"
          >
            <FolderSearch className="w-4 h-4" />
            Browse & Add
          </button>
        </div>

        {/* List */}
        {dirs.length === 0 ? (
          <div className="py-8 text-center">
            <FolderOpen className="w-10 h-10 text-text-muted mx-auto mb-3" />
            <p className="text-text-secondary font-medium">No directories configured</p>
            <p className="text-text-muted text-sm mt-1">
              Click "Browse & Add" to select folders containing your projects
            </p>
          </div>
        ) : (
          <div className="space-y-2">
            {dirs.map((dir) => (
              <div
                key={dir}
                className="flex items-center justify-between bg-surface-2 rounded-lg px-4 py-3 group"
              >
                <div className="flex items-center gap-3 min-w-0">
                  <FolderOpen className="w-4 h-4 text-text-muted shrink-0" />
                  <span className="text-sm font-mono text-text-secondary truncate">{dir}</span>
                </div>
                <button
                  onClick={() => handleRemove(dir)}
                  className="p-1.5 rounded-md text-text-muted hover:text-red hover:bg-red-muted transition-colors opacity-0 group-hover:opacity-100"
                >
                  <Trash2 className="w-4 h-4" />
                </button>
              </div>
            ))}
          </div>
        )}
      </div>

      {/* Claude Settings */}
      <div className="bg-surface border border-border rounded-xl p-5 mt-6">
        <div className="flex items-center justify-between mb-4">
          <div>
            <h2 className="text-base font-semibold">Claude Settings</h2>
            <p className="text-xs text-text-muted mt-0.5">~/.claude/settings.json — Claude Code model, effort level, and permissions</p>
          </div>

import { useState, useEffect } from 'react'
import { Globe, Plus, Trash2, Copy, Eye, EyeOff, AlertCircle, Check } from 'lucide-react'
import { getWebhooks, getWebhookSecret, createWebhook, deleteWebhook, getGlobalAgents } from '../lib/api'
import type { Webhook } from '../lib/api'
import type { Agent } from '../types'

function timeAgo(ts: string | null): string {
  if (!ts) return 'never'
  const diff = Date.now() - new Date(ts).getTime()
  if (diff < 60000) return 'just now'
  if (diff < 3600000) return `${Math.floor(diff / 60000)}m ago`
  if (diff < 86400000) return `${Math.floor(diff / 3600000)}h ago`
  return `${Math.floor(diff / 86400000)}d ago`
}

export default function WebhooksPage() {
  const [webhooks, setWebhooks] = useState<Webhook[]>([])
  const [agents, setAgents] = useState<Agent[]>([])
  const [loading, setLoading] = useState(true)
  const [showForm, setShowForm] = useState(false)
  const [form, setForm] = useState({ name: '', agentName: '' })
  const [saving, setSaving] = useState(false)
  const [error, setError] = useState('')
  const [revealedSecrets, setRevealedSecrets] = useState<Record<string, string>>({})
  const [copied, setCopied] = useState('')

  const load = () => {
    setLoading(true)
    Promise.all([getWebhooks(), getGlobalAgents()])
      .then(([w, a]) => { setWebhooks(w); setAgents(a) })
      .catch(() => {})
      .finally(() => setLoading(false))
  }

  useEffect(() => { load() }, [])

  const handleCreate = async () => {
    if (!form.name || !form.agentName) { setError('Name and agent are required'); return }
    setSaving(true); setError('')
    try {
      await createWebhook(form)
      setShowForm(false)
      setForm({ name: '', agentName: '' })
      load()
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to create webhook')
    } finally { setSaving(false) }
  }

  const handleDelete = async (id: string) => {
    if (!confirm('Delete this webhook?')) return
    try { await deleteWebhook(id); load() } catch {}
  }

  const handleRevealSecret = async (id: string) => {
    if (revealedSecrets[id]) {
      setRevealedSecrets(prev => { const next = { ...prev }; delete next[id]; return next })
      return
    }
    try {
      const { secret } = await getWebhookSecret(id)
      setRevealedSecrets(prev => ({ ...prev, [id]: secret }))
    } catch {}
  }

  const copyToClipboard = (text: string, label: string) => {
    navigator.clipboard.writeText(text)
    setCopied(label)
    setTimeout(() => setCopied(''), 2000)
  }

  const getTriggerUrl = (id: string) => `${window.location.origin}/api/webhooks/trigger/${id}`

  if (loading) return <div className="p-8 text-text-muted">Loading webhooks...</div>

  return (
    <div className="max-w-4xl mx-auto p-8 space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold flex items-center gap-2">
            <Globe className="w-6 h-6" /> Webhooks
          </h1>
          <p className="text-text-muted text-sm mt-1">Trigger agents from external events (GitHub, Stripe, etc.)</p>
        </div>
        <button
          onClick={() => setShowForm(!showForm)}
          className="flex items-center gap-2 px-4 py-2 text-sm font-medium rounded-lg bg-accent text-white hover:bg-accent-hover transition-colors"
        >
          <Plus className="w-4 h-4" /> New Webhook
        </button>
      </div>

      {/* Create Form */}
      {showForm && (
        <div className="bg-surface rounded-xl border border-border p-5 space-y-4">
          <h2 className="text-sm font-semibold">Create Webhook</h2>
          {error && (
            <div className="flex items-center gap-2 text-red-400 text-xs bg-red-500/10 px-3 py-2 rounded-lg">
              <AlertCircle className="w-3.5 h-3.5" /> {error}
            </div>
          )}
          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-xs text-text-muted mb-1">Name</label>
              <input
                className="w-full px-3 py-2 text-sm bg-surface-2 border border-border rounded-lg focus:border-accent outline-none"
                placeholder="GitHub Deploy Hook"
                value={form.name}
                onChange={e => setForm({ ...form, name: e.target.value })}
              />
            </div>
            <div>
              <label className="block text-xs text-text-muted mb-1">Agent</label>
              <select
                className="w-full px-3 py-2 text-sm bg-surface-2 border border-border rounded-lg focus:border-accent outline-none"
                value={form.agentName}
                onChange={e => setForm({ ...form, agentName: e.target.value })}
              >
                <option value="">Select agent...</option>
                {agents.map(a => (
                  <option key={a.filename} value={a.filename}>{a.name}</option>
                ))}
              </select>
            </div>
          </div>
          <div className="flex justify-end gap-2">
            <button onClick={() => setShowForm(false)} className="px-4 py-2 text-sm rounded-lg bg-surface-2 hover:bg-surface-2/80">Cancel</button>
            <button
              onClick={handleCreate}
              disabled={saving}
              className="px-4 py-2 text-sm font-medium rounded-lg bg-accent text-white hover:bg-accent-hover disabled:opacity-50"
            >
              {saving ? 'Creating...' : 'Create Webhook'}
            </button>
          </div>
        </div>
      )}

      {/* Webhook List */}
      <div className="space-y-3">
        {webhooks.map(w => (
          <div key={w.id} className="bg-surface rounded-xl border border-border p-4 space-y-3">
            <div className="flex items-center justify-between">
