// ─── Types ──────────────────────────────────────────────────────────────────

interface TestResult {
  id: string
  agent: string
  agentName: string
  prompt: string
  output: string
  duration: number
  status: 'success' | 'error'
  timestamp: Date
}

interface PlaygroundSettings {
  timeoutMs: number
  customInstructions: string
  outputMode: 'markdown' | 'raw'
}

const STORAGE_KEY = 'polyglot:playground-history'
const SETTINGS_KEY = 'polyglot:playground-settings'

const DEFAULT_SETTINGS: PlaygroundSettings = {
  timeoutMs: 120000,
  customInstructions: '',
  outputMode: 'markdown',
}

// ─── Helpers ────────────────────────────────────────────────────────────────

function loadPersistedHistory(): TestResult[] {
  try {
    const raw = localStorage.getItem(STORAGE_KEY)
    if (!raw) return []
    const parsed = JSON.parse(raw)
    return parsed.map((r: TestResult) => ({ ...r, timestamp: new Date(r.timestamp) }))
  } catch { return [] }
}

function loadPersistedSettings(): PlaygroundSettings {
  try {
    const raw = localStorage.getItem(SETTINGS_KEY)
    if (!raw) return DEFAULT_SETTINGS
    return { ...DEFAULT_SETTINGS, ...JSON.parse(raw) }
  } catch { return DEFAULT_SETTINGS }
}

function formatDuration(ms: number): string {
  if (ms < 1000) return `${ms}ms`
  if (ms < 60000) return `${(ms / 1000).toFixed(1)}s`
  const min = Math.floor(ms / 60000)
  const sec = ((ms % 60000) / 1000).toFixed(0)
  return `${min}m ${sec}s`
}

function formatTime(date: Date): string {
  return date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
}

