      } : null)
      setStreamingContent('')
      loadConvos()
    } catch (err) {
      if ((err as Error).name !== 'AbortError') {
        setActiveConvo(prev => prev ? {
          ...prev,
          messages: [...prev.messages, { role: 'assistant', content: `Error: ${(err as Error).message}`, timestamp: new Date().toISOString() }],
        } : null)
      }
      setStreamingContent('')
    } finally {
      setSending(false)
      abortRef.current = null
    }
  }

